from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parent
STATIC_DIR = ROOT / "static"
DATA_DIR = Path(os.environ.get("YS_DATA_DIR", str(ROOT / "data"))).expanduser().resolve()
UPLOAD_DIR = DATA_DIR / "uploads"
DB_PATH = Path(os.environ.get("YS_DB_PATH", str(DATA_DIR / "ys_shopping.sqlite3"))).expanduser().resolve()
COOKIE_NAME = "ys_session"
SESSION_SECONDS = 7 * 24 * 60 * 60
MAX_BODY = 6 * 1024 * 1024
MAX_IMAGE = 3 * 1024 * 1024
PBKDF2_ROUNDS = 310_000

DATA_DIR.mkdir(parents=True, exist_ok=True)
UPLOAD_DIR.mkdir(parents=True, exist_ok=True)


def utc_now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def local_now() -> datetime:
    return datetime.now()


def money(value: Any) -> str:
    try:
        return f"{int(value):,}".replace(",", ".") + "đ"
    except (ValueError, TypeError):
        return "0đ"


def esc(value: Any) -> str:
    return html.escape("" if value is None else str(value), quote=True)


def clean_text(value: Any, limit: int = 4000) -> str:
    return str(value or "").strip()[:limit]


def parse_int(value: Any, default: int = 0) -> int:
    try:
        return int(str(value).strip())
    except (ValueError, TypeError):
        return default


def valid_image_bytes(filename: str, content_type: str, data: bytes) -> tuple[bool, str]:
    if not filename or not data or len(data) > MAX_IMAGE:
        return False, "Ảnh trống hoặc vượt quá 3 MB."
    ext = Path(filename).suffix.lower()
    signatures = {
        ".png": ("image/png", data.startswith(b"\x89PNG\r\n\x1a\n")),
        ".jpg": ("image/jpeg", data.startswith(b"\xff\xd8\xff")),
        ".jpeg": ("image/jpeg", data.startswith(b"\xff\xd8\xff")),
        ".webp": ("image/webp", data.startswith(b"RIFF") and data[8:12] == b"WEBP"),
    }
    if ext not in signatures or not signatures[ext][1]:
        return False, "Chỉ nhận ảnh JPG, PNG hoặc WebP hợp lệ."
    return True, signatures[ext][0]


def safe_image_path(filename: str) -> Path | None:
    # Upload names are generated by the server, but still enforce a strict basename.
    if not filename or filename != Path(filename).name or not re.fullmatch(r"[A-Za-z0-9_.-]{1,180}", filename):
        return None
    candidate = (UPLOAD_DIR / filename).resolve()
    try:
        candidate.relative_to(UPLOAD_DIR.resolve())
    except ValueError:
        return None
    return candidate if candidate.is_file() else None


class ClosingConnection(sqlite3.Connection):
    def __exit__(self, exc_type: Any, exc: Any, tb: Any) -> bool:
        try:
            return super().__exit__(exc_type, exc, tb)
        finally:
            self.close()


def connect_db() -> sqlite3.Connection:
    con = sqlite3.connect(DB_PATH, timeout=12, isolation_level=None, factory=ClosingConnection)
    con.row_factory = sqlite3.Row
    con.execute("PRAGMA foreign_keys = ON")
    con.execute("PRAGMA busy_timeout = 12000")
    con.execute("PRAGMA journal_mode = WAL")
    return con


