def setting(key: str, default: str = "") -> str:
    with connect_db() as con:
        row = con.execute("SELECT value FROM settings WHERE key=?", (key,)).fetchone()
        return row["value"] if row else default


def save_setting(con: sqlite3.Connection, key: str, value: str) -> None:
    con.execute("INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value", (key, value))


def hash_password(password: str) -> str:
    salt = secrets.token_bytes(16)
    digest = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, PBKDF2_ROUNDS)
    return f"pbkdf2_sha256${PBKDF2_ROUNDS}${salt.hex()}${digest.hex()}"


def verify_password(password: str, encoded: str) -> bool:
    try:
        algorithm, rounds, salt_hex, expected = encoded.split("$", 3)
        if algorithm != "pbkdf2_sha256":
            return False
        digest = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), bytes.fromhex(salt_hex), int(rounds)).hex()
        return hmac.compare_digest(digest, expected)
    except (ValueError, TypeError):
        return False


def audit(con: sqlite3.Connection, actor: sqlite3.Row | None, action: str, target_type: str = "", target_id: Any = "", detail: str = "") -> None:
    name = actor["username"] if actor else "system"
    con.execute(
        "INSERT INTO audit_log(actor_id,actor_name,action,target_type,target_id,detail,created_at) VALUES(?,?,?,?,?,?,?)",
        (actor["id"] if actor else None, name, action, target_type, str(target_id), clean_text(detail, 1000), utc_now()),
    )


def send_discord(message: str) -> None:
    """Best-effort server-side notification; never include credentials or payment secrets."""
    webhook = setting("discord_webhook", "").strip()
    if not webhook or not webhook.startswith("https://") or len(webhook) > 500:
        return
    data = json.dumps({"content": message[:1800]}).encode("utf-8")
    req = urllib.request.Request(webhook, data=data, headers={"Content-Type": "application/json", "User-Agent": "YS-Shopping/1.0"}, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=2) as response:
            response.read(128)
    except (urllib.error.URLError, TimeoutError, OSError):
        pass


def ensure_setup_token() -> str | None:
    with connect_db() as con:
        count = con.execute("SELECT COUNT(*) AS c FROM users WHERE role='admin'").fetchone()["c"]
    if count:
        token_file = DATA_DIR / "setup.token"
        if token_file.exists():
            try:
                token_file.unlink()
            except OSError:
                pass
        return None
    token_file = DATA_DIR / "setup.token"
    if token_file.exists():
        try:
            return token_file.read_text(encoding="utf-8").strip()
        except OSError:
            pass
    token = secrets.token_urlsafe(32)
    token_file.write_text(token, encoding="utf-8")
    try:
        token_file.chmod(0o600)
    except OSError:
        pass
    return token


def admin_exists() -> bool:
    with connect_db() as con:
        return con.execute("SELECT 1 FROM users WHERE role='admin' LIMIT 1").fetchone() is not None


def image_upload(handler: "StoreHandler", field: str, prefix: str) -> tuple[str | None, str | None]:
    upload = handler.files.get(field)
    if not upload or not upload.get("data"):
        return None, None
    filename = upload.get("filename", "")
    data = upload.get("data", b"")
    ok, content_type = valid_image_bytes(filename, upload.get("content_type", ""), data)
    if not ok:
        return None, content_type
    suffix = {"image/jpeg": ".jpg", "image/png": ".png", "image/webp": ".webp"}[content_type]
    out = f"{prefix}_{int(time.time())}_{secrets.token_hex(4)}{suffix}"
    path = UPLOAD_DIR / out
    path.write_bytes(data)
    return f"/uploads/{out}", None


class StoreHandler(BaseHTTPRequestHandler):
    server_version = "YSShopping/1.0"
    sys_version = ""

    def log_message(self, fmt: str, *args: Any) -> None:
        # Keep operational logs useful without dumping form content, QR data or webhooks.
        print(f"[{self.log_date_time_string()}] {self.client_address[0]} {fmt % args}")

    def do_GET(self) -> None:
        try:
            self._handle("GET")
        except Exception as exc:
            print(f"GET handler error: {type(exc).__name__}: {exc}")
            try: self.send_html(self.error_page(500, "Có lỗi ngoài dự kiến. Dữ liệu chưa chắc đã được thay đổi; hãy kiểm tra trang và nhật ký rồi thử lại.", getattr(self, "session", None)), 500)
            except Exception: pass

    def do_POST(self) -> None:
        try:
            self._handle("POST")
        except Exception as exc:
            print(f"POST handler error: {type(exc).__name__}: {exc}")
            try: self.send_html(self.error_page(500, "Có lỗi ngoài dự kiến. Không gửi lặp thanh toán; hãy kiểm tra trạng thái đơn trước khi thử lại.", getattr(self, "session", None)), 500)
            except Exception: pass

    def _handle(self, method: str) -> None:
        self.method = method
        parsed = urllib.parse.urlparse(self.path)
        self.path_only = parsed.path
        self.query = urllib.parse.parse_qs(parsed.query, keep_blank_values=True)
        self.form: dict[str, str] = {}
        self.files: dict[str, dict[str, Any]] = {}
        self.new_cookie: str | None = None
        self.clear_cookie = False
        self.session = self._load_session()
        if method == "POST":
            try:
                length = int(self.headers.get("Content-Length", "0"))
            except ValueError:
                length = 0
            if length < 0 or length > MAX_BODY:
                return self.send_html(self.error_page(413, "Tệp hoặc dữ liệu gửi lên quá lớn.", self.session), 413)
            raw = self.rfile.read(length) if length else b""
            self.form, self.files = self._parse_body(raw, self.headers.get("Content-Type", ""))
            submitted = self.form.get("csrf", "")
            if not self.session or not hmac.compare_digest(submitted, self.session["csrf"]):
                return self.send_html(self.error_page(403, "Phiên gửi biểu mẫu đã hết hạn. Hãy tải lại trang rồi thử lại.", self.session), 403)
            self._post_route()
        else:
            self._get_route()

    def _parse_body(self, raw: bytes, content_type: str) -> tuple[dict[str, str], dict[str, dict[str, Any]]]:
        fields: dict[str, str] = {}
        uploads: dict[str, dict[str, Any]] = {}
        if content_type.lower().startswith("multipart/form-data"):
            try:
                message = BytesParser(policy=email_policy).parsebytes(
                    b"MIME-Version: 1.0\r\nContent-Type: " + content_type.encode("utf-8", "replace") + b"\r\n\r\n" + raw
                )
                if message.is_multipart():
                    for part in message.iter_parts():
                        name = part.get_param("name", header="content-disposition")
                        if not name:
                            continue
                        filename = part.get_filename()
                        payload = part.get_payload(decode=True) or b""
                        if filename is not None:
                            uploads[name] = {"filename": Path(filename.replace("\\", "/")).name, "content_type": part.get_content_type(), "data": payload}
                        else:
                            charset = part.get_content_charset() or "utf-8"
                            fields[name] = payload.decode(charset, "replace")
            except Exception:
                return {}, {}
        else:
            parsed = urllib.parse.parse_qs(raw.decode("utf-8", "replace"), keep_blank_values=True, max_num_fields=1200)
            fields = {k: v[-1] for k, v in parsed.items()}
        return fields, uploads

    def _load_session(self) -> sqlite3.Row | None:
        cookie = SimpleCookie()
        try:
            cookie.load(self.headers.get("Cookie", ""))
            token = cookie[COOKIE_NAME].value
        except (KeyError, Exception):
            token = ""
        if token:
            token_hash = hashlib.sha256(token.encode("utf-8")).hexdigest()
            with connect_db() as con:
                row = con.execute(
                    "SELECT s.token_hash,s.user_id,s.csrf,s.expires_at,u.id,u.username,u.email,u.role,u.disabled,u.balance,u.created_at "
                    "FROM sessions s LEFT JOIN users u ON u.id=s.user_id WHERE s.token_hash=? AND s.expires_at>?",
                    (token_hash, int(time.time())),
                ).fetchone()
                if row:
                    if row["user_id"] is not None and (row["disabled"] or not row["id"]):
                        con.execute("DELETE FROM sessions WHERE token_hash=?", (token_hash,))
                    else:
                        self.session_token = token
                        return row
        return self._new_session(None)

    def _new_session(self, user_id: int | None) -> sqlite3.Row:
        token = secrets.token_urlsafe(32)
        csrf = secrets.token_urlsafe(24)
        token_hash = hashlib.sha256(token.encode("utf-8")).hexdigest()
        now = int(time.time())
        with connect_db() as con:
            con.execute("INSERT INTO sessions(token_hash,user_id,csrf,expires_at,created_at) VALUES(?,?,?,?,?)", (token_hash, user_id, csrf, now + SESSION_SECONDS, utc_now()))
            if user_id is None:
                row = con.execute("SELECT token_hash,user_id,csrf,expires_at,NULL AS id,NULL AS username,NULL AS email,NULL AS role,NULL AS disabled,0 AS balance,'' AS created_at FROM sessions WHERE token_hash=?", (token_hash,)).fetchone()
            else:
                row = con.execute(
                    "SELECT s.token_hash,s.user_id,s.csrf,s.expires_at,u.id,u.username,u.email,u.role,u.disabled,u.balance,u.created_at "
                    "FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=?", (token_hash,)
                ).fetchone()
        self.session_token = token
        self.new_cookie = token
        return row

    def _refresh_session(self, user_id: int | None) -> None:
        old = getattr(self, "session_token", None)
        if old:
            with connect_db() as con:
                con.execute("DELETE FROM sessions WHERE token_hash=?", (hashlib.sha256(old.encode()).hexdigest(),))
        self.session = self._new_session(user_id)

    def _get_route(self) -> None:
        path = self.path_only
        if path.startswith("/static/"):
            return self._send_static(path[len("/static/"):], static=True)
        if path.startswith("/uploads/"):
            return self._send_static(path[len("/uploads/"):], static=False)
        if path == "/robots.txt":
            body = "User-agent: *\nDisallow: /admin\nDisallow: /account\nDisallow: /wallet\nDisallow: /orders\n"
            public_url = os.environ.get("YS_PUBLIC_URL", "").rstrip("/")
            if public_url: body += f"Sitemap: {public_url}/sitemap.xml\n"
            data = body.encode("utf-8")
            self.send_response(200); self.send_header("Content-Type", "text/plain; charset=utf-8"); self.send_header("Content-Length", str(len(data))); self._security_headers(); self._cookie_header(); self.end_headers(); self.wfile.write(data)
            return
        if path == "/sitemap.xml":
            public_url = os.environ.get("YS_PUBLIC_URL", "").rstrip("/")
            if not public_url: return self.send_html(self.error_page(404, "Chưa cấu hình YS_PUBLIC_URL cho sitemap.", self.session), 404)
            urls = ["/", "/login", "/register"]
            xml = '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">' + ''.join('<url><loc>'+html.escape(public_url + u)+'</loc></url>' for u in urls) + '</urlset>'
            data = xml.encode("utf-8")
            self.send_response(200); self.send_header("Content-Type", "application/xml; charset=utf-8"); self.send_header("Content-Length", str(len(data))); self._security_headers(); self._cookie_header(); self.end_headers(); self.wfile.write(data)
            return
        if path == "/health":
            return self.send_json({"ok": True, "service": "YS Shopping", "database": DB_PATH.exists()})
        if path == "/favicon.ico":
            return self.redirect("/static/images/hero-art.jpg")
        if path == "/setup":
            return self.setup_get()
        if path == "/":
            return self.home()
        if path == "/login":
            return self.login_get()
        if path == "/register":
            return self.register_get()
        if path == "/wallet":
            if not self.require_login(): return
            return self.wallet_get()
        if path == "/orders":
            if not self.require_login(): return
            return self.orders_get()
        if path == "/account":
            if not self.require_login(): return
            return self.account_get()
        if path == "/admin" or path.startswith("/admin/"):
            if not self.require_role("staff", "admin"): return
            return self.admin_get(path)
        return self.send_html(self.error_page(404, "Trang này chưa tồn tại.", self.session), 404)

    def _post_route(self) -> None:
        path = self.path_only
        if path == "/setup": return self.setup_post()
        if path == "/login": return self.login_post()
        if path == "/register": return self.register_post()
        if path == "/logout":
            token = getattr(self, "session_token", "")
            if token:
                with connect_db() as con:
                    con.execute("DELETE FROM sessions WHERE token_hash=?", (hashlib.sha256(token.encode()).hexdigest(),))
            self.clear_cookie = True
            return self.redirect("/?msg=Đã%20đăng%20xuất&kind=ok")
        if path == "/wallet/topup":
            if not self.require_login(): return
            return self.topup_post()
        if path.startswith("/buy/"):
            if not self.require_login(): return
            return self.buy_post(parse_int(path.rsplit("/", 1)[-1], -1))
        if path == "/account/password":
            if not self.require_login(): return
            return self.password_post()
        if path.startswith("/admin/") or path == "/admin":
            if not self.require_role("staff", "admin"): return
            return self.admin_post(path)
        return self.send_html(self.error_page(404, "Đường dẫn không tồn tại.", self.session), 404)

    def _send_static(self, rel: str, static: bool) -> None:
        base = STATIC_DIR if static else UPLOAD_DIR
        rel = urllib.parse.unquote(rel)
        path = (base / rel).resolve()
        try:
            path.relative_to(base.resolve())
        except ValueError:
            return self.send_html(self.error_page(404, "Không tìm thấy tệp.", self.session), 404)
        if not path.is_file():
            return self.send_html(self.error_page(404, "Không tìm thấy tệp.", self.session), 404)
        data = path.read_bytes()
        ctype = mimetypes.guess_type(path.name)[0] or "application/octet-stream"
        self.send_response(200)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(data)))
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("Cache-Control", "public, max-age=3600")
        self._cookie_header()
        self.end_headers()
        self.wfile.write(data)

    def _security_headers(self) -> None:
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("X-Frame-Options", "DENY")
        self.send_header("Referrer-Policy", "strict-origin-when-cross-origin")
        self.send_header("Permissions-Policy", "camera=(), microphone=(), geolocation=()")
        self.send_header("Content-Security-Policy", "default-src 'self'; img-src 'self' data: https:; style-src 'self' 'unsafe-inline'; script-src 'self'; base-uri 'self'; form-action 'self'; frame-ancestors 'none'")
        self.send_header("Cache-Control", "no-store")

    def _cookie_header(self) -> None:
        if self.clear_cookie:
            self.send_header("Set-Cookie", f"{COOKIE_NAME}=; Path=/; Max-Age=0; HttpOnly; SameSite=Lax")
        elif self.new_cookie:
            secure = "; Secure" if os.environ.get("YS_COOKIE_SECURE", "0") == "1" or self.headers.get("X-Forwarded-Proto", "").lower() == "https" else ""
            self.send_header("Set-Cookie", f"{COOKIE_NAME}={self.new_cookie}; Path=/; Max-Age={SESSION_SECONDS}; HttpOnly; SameSite=Lax{secure}")

    def send_html(self, body: str, status: int = 200) -> None:
        data = body.encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(data)))
        self._security_headers()
        self._cookie_header()
        self.end_headers()
        try: self.wfile.write(data)
        except BrokenPipeError: pass

    def send_json(self, obj: dict[str, Any], status: int = 200) -> None:
        data = json.dumps(obj, ensure_ascii=False).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(data)))
        self._security_headers()
        self._cookie_header()
        self.end_headers()
        self.wfile.write(data)

    def redirect(self, location: str, status: int = 303) -> None:
        # HTTP headers are Latin-1; percent-encode non-ASCII query text in redirects.
        location = urllib.parse.quote(location, safe="/:?=&%#;,+-._~")
        self.send_response(status)
        self.send_header("Location", location)
        self.send_header("Content-Length", "0")
        self._security_headers()
        self._cookie_header()
        self.end_headers()

    def error_page(self, code: int, message: str, session: sqlite3.Row | None = None) -> str:
        return self.page(f"{code} · YS Shopping", f'<section class="panel empty"><span class="eyebrow">LỖI {code}</span><h1>{esc(message)}</h1><p>Hãy quay lại trang trước hoặc trở về cửa hàng.</p><a class="btn primary" href="/">Về trang chủ</a></section>', session)

    def page(self, title: str, body: str, session: sqlite3.Row | None = None, wide: bool = False) -> str:
        u = session if session and session["id"] is not None else None
        qmsg = self.query.get("msg", [""])[-1]
        kind = self.query.get("kind", ["info"])[-1]
        notice = f'<div class="notice {esc(kind)}">{esc(qmsg)}</div>' if qmsg else ""
        shop_name = esc(setting("shop_name", "YS Shopping"))
        tagline = esc(setting("tagline", "Tông Môn Giao Dịch · Vạn Giới Kết Duyên"))
        if u:
            account = f'<div class="user-chip"><span class="avatar">{esc(u["username"][:1].upper())}</span><span><b>{esc(u["username"])}</b><small>{money(u["balance"])}</small></span></div>'
            auth_actions = f'<a class="nav-link" href="/account">Tài khoản</a>'
            if u["role"] in ("admin", "staff"):
                auth_actions += '<a class="nav-link admin-link" href="/admin">Quản trị</a>'
            auth_actions += f'<form class="inline" method="post" action="/logout"><input type="hidden" name="csrf" value="{esc(session["csrf"])}"><button class="nav-ghost" type="submit">Thoát</button></form>'
        else:
            account = '<a class="nav-link" href="/login">Đăng nhập</a><a class="btn small primary" href="/register">Gia nhập tông môn</a>'
            auth_actions = ''
        wrapclass = "container wide" if wide else "container"
        return f'''<!doctype html>
<html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><meta name="theme-color" content="#0b1021"><meta name="description" content="YS Shopping — gian hàng vật phẩm số phong cách tiên hiệp."><title>{esc(title)} · {shop_name}</title><link rel="stylesheet" href="/static/style.css"></head>
<body><div class="ambient ambient-a"></div><div class="ambient ambient-b"></div>
<header class="topbar"><div class="top-inner"><a class="brand" href="/" aria-label="YS Shopping trang chủ"><span class="brand-mark">YS</span><span class="brand-copy"><strong>{shop_name}</strong><small>{tagline}</small></span></a><button class="menu-toggle" type="button" aria-label="Mở menu" data-menu-toggle>☰</button><nav class="nav" data-menu>{'<a class="nav-link" href="/">Trang chủ</a><a class="nav-link" href="/#shop">Gian hàng</a><a class="nav-link" href="/wallet">Nạp tiền</a><a class="nav-link" href="/orders">Đơn hàng</a>' + auth_actions}</nav><div class="top-account">{account}</div></div></header>
<main class="{wrapclass}">{notice}{body}</main>
<footer class="footer"><div class="footer-brand"><span class="brand-mark small-mark">YS</span><span><b>YS Shopping</b><small>Vạn vật đều có duyên.</small></span></div><p>Giao dịch rõ ràng · Bảo vệ tài khoản · Hỗ trợ khi cần</p>{('<p><a href="'+esc(setting("support_link"))+ '" target="_blank" rel="noopener noreferrer nofollow">Liên hệ hỗ trợ ↗</a></p>') if setting("support_link") else ''}<small>© {datetime.now().year} YS Shopping. Vui lòng kiểm tra kỹ thông tin trước khi thanh toán.</small></footer>
<script src="/static/app.js" defer></script></body></html>'''

    def current_user(self) -> sqlite3.Row | None:
        if self.session and self.session["id"] is not None:
            return self.session
        return None

    def require_login(self) -> bool:
        user = self.current_user()
        if not user:
            self.redirect("/login?msg=Vui%20lòng%20đăng%20nhập%20trước&kind=info")
            return False
        if user["disabled"]:
            self.send_html(self.error_page(403, "Tài khoản đang bị khóa.", self.session), 403)
            return False
        return True

    def require_role(self, *roles: str) -> bool:
        if not self.require_login():
            return False
        if self.current_user()["role"] not in roles:
            self.send_html(self.error_page(403, "Ní không có quyền truy cập khu vực này.", self.session), 403)
            return False
        return True

    def hidden_csrf(self) -> str:
        return f'<input type="hidden" name="csrf" value="{esc(self.session["csrf"])}">'

    def setup_get(self) -> None:
        if admin_exists():
            return self.redirect("/login?msg=Thiết%20lập%20Admin%20đã%20hoàn%20tất&kind=info")
        token_file = DATA_DIR / "setup.token"
        saved = token_file.read_text(encoding="utf-8").strip() if token_file.exists() else ""
        token = self.query.get("token", [""])[-1]
        if not saved or not hmac.compare_digest(token, saved):
            return self.send_html(self.error_page(403, "Liên kết thiết lập Admin không hợp lệ. Hãy lấy mã từ cửa sổ chạy máy chủ.", self.session), 403)
        body = f'''<section class="auth-layout"><div class="auth-art"><span class="eyebrow">KHỞI MỞ TÔNG MÔN</span><h1>Thiết lập<br><em>Admin đầu tiên</em></h1><p>Đây là bước bảo vệ cửa hàng. Chỉ người có mã thiết lập từ máy chủ mới tạo được Admin đầu tiên.</p></div><div class="panel form-panel"><h2>Tạo tài khoản quản trị</h2><p class="muted">Mật khẩu nên có ít nhất 12 ký tự, khó đoán và chỉ dùng cho YS Shopping.</p><form method="post" action="/setup" class="stack">{self.hidden_csrf()}<input type="hidden" name="setup_token" value="{esc(token)}"><label>Tên đăng nhập<input name="username" autocomplete="username" minlength="3" maxlength="24" required pattern="[A-Za-z0-9_-]+"></label><label>Mật khẩu Admin<input name="password" type="password" autocomplete="new-password" minlength="12" required></label><label>Nhập lại mật khẩu<input name="password2" type="password" autocomplete="new-password" minlength="12" required></label><button class="btn primary full" type="submit">Tạo Admin an toàn</button></form></div></section>'''
        self.send_html(self.page("Thiết lập Admin", body, self.session, wide=True))

    def setup_post(self) -> None:
        if admin_exists():
            return self.redirect("/login?msg=Admin%20đã%20được%20thiết%20lập&kind=info")
        token_file = DATA_DIR / "setup.token"
        saved = token_file.read_text(encoding="utf-8").strip() if token_file.exists() else ""
        token = self.form.get("setup_token", "")
        username = clean_text(self.form.get("username"), 24)
        password = self.form.get("password", "")
        password2 = self.form.get("password2", "")
        if not saved or not hmac.compare_digest(token, saved):
            return self.send_html(self.error_page(403, "Mã thiết lập Admin không hợp lệ.", self.session), 403)
        if not re.fullmatch(r"[A-Za-z0-9_-]{3,24}", username):
            return self.redirect("/setup?token=" + urllib.parse.quote(token) + "&msg=Tên%20đăng%20nhập%20không%20hợp%20lệ&kind=error")
        if len(password) < 12 or password != password2:
            return self.redirect("/setup?token=" + urllib.parse.quote(token) + "&msg=Mật%20khẩu%20phải%20từ%2012%20ký%20tự%20và%20hai%20ô%20phải%20trùng%20nhau&kind=error")
        try:
            with connect_db() as con:
                con.execute("BEGIN IMMEDIATE")
                if con.execute("SELECT 1 FROM users WHERE role='admin'").fetchone():
                    con.rollback()
                    return self.redirect("/login")
                cur = con.execute("INSERT INTO users(username,password_hash,role,created_at) VALUES(?,?,?,?)", (username, hash_password(password), "admin", utc_now()))
                audit(con, con.execute("SELECT * FROM users WHERE id=?", (cur.lastrowid,)).fetchone(), "first_admin_created", "user", cur.lastrowid, "Khởi tạo Admin đầu tiên")
                con.commit()
            try: token_file.unlink()
            except OSError: pass
            self._refresh_session(cur.lastrowid)
            return self.redirect("/admin?msg=Đã%20tạo%20Admin%20thành%20công&kind=ok")
        except sqlite3.IntegrityError:
            return self.redirect("/setup?token=" + urllib.parse.quote(token) + "&msg=Tên%20đăng%20nhập%20đã%20được%20dùng&kind=error")

    def home(self) -> None:
        announcement = setting("announcement", "")
        banner = setting("promo_banner", "")
        hero = esc(setting("hero_image", "/static/images/hero-art.jpg"))
        with connect_db() as con:
            products = con.execute("SELECT * FROM products WHERE is_active=1 ORDER BY id DESC").fetchall()
        cards = []
        now = local_now()
        for p in products:
            current_price = p["price"]
            sale = False
            if p["sale_price"] is not None and p["sale_price"] > 0 and p["sale_price"] < p["price"]:
                try:
                    until = datetime.fromisoformat(p["sale_until"]) if p["sale_until"] else None
                    if until and until >= now:
                        current_price, sale = p["sale_price"], True
                except ValueError:
                    pass
            stock = self.stock_count(p)
            stock_label = "Còn hàng" if p["stock_mode"] == "unlimited" or stock > 0 else "Tạm hết hàng"
            image = f'<img src="{esc(p["image_url"])}" alt="{esc(p["title"])}" loading="lazy">' if p["image_url"] else '<div class="product-art"><span>✧</span><b>YS</b><small>Bảo vật Bồng Lai</small></div>'
            price_html = f'<strong>{money(current_price)}</strong>' + (f'<del>{money(p["price"])}</del>' if sale else "")
            buy_button = f'<form method="post" action="/buy/{p["id"]}">{self.hidden_csrf()}<input type="text" name="coupon" maxlength="32" placeholder="Mã ưu đãi (nếu có)" class="coupon-input"><button class="btn primary full" type="submit" {"disabled" if (p["stock_mode"] != "unlimited" and stock < 1) else ""}>Thỉnh bảo vật</button></form>'
            desc = esc(p["description"][:180])
            cards.append(f'''<article class="product-card" data-title="{esc(p['title'] + ' ' + p['description'])}" data-category="{esc(p['category'])}"><a class="product-image" href="#shop">{image}<span class="category-pill">{esc(p["category"])}</span></a><div class="product-content"><div class="product-title-row"><h3>{esc(p["title"])}</h3><span class="stock-dot {'out' if stock_label!='Còn hàng' else ''}"></span></div><p>{desc}</p><div class="product-meta"><span>{stock_label if p['stock_mode']!='unlimited' else 'Giao dịch số'}</span><span class="price">{price_html}</span></div>{buy_button}</div></article>''')
        catalog = "".join(cards) if cards else '''<div class="empty-store"><div class="empty-seal">✧</div><h3>Kho báu đang chờ khai mở</h3><p>Chưa có sản phẩm nào được đăng bán. Admin có thể thêm sản phẩm, giá và mã hàng trong khu vực Quản trị.</p></div>'''
        user = self.current_user()
        wallet = f'<div class="hero-balance"><span>Số dư hiện tại</span><strong>{money(user["balance"]) if user else "Đăng nhập để xem"}</strong><a href="/wallet">Nạp số dư ↗</a></div>'
        body = f'''<section class="hero" style="--hero-image:url('{hero}')"><div class="hero-overlay"></div><div class="hero-copy"><span class="eyebrow"><span class="eyebrow-dot"></span> TIÊN CẢNH HỘI TỤ</span><h1>Mở cánh cổng<br><em>Tiên Cảnh</em></h1><p>Khám phá bảo vật số, tài khoản và những gói dịch vụ được tuyển chọn trong một không gian huyền ảo.</p><div class="hero-actions"><a class="btn primary" href="#shop">Khám phá gian hàng <span>↗</span></a><a class="btn ghost" href="/wallet">Nạp số dư</a></div><div class="hero-trust"><span>✦ Giao dịch rõ ràng</span><span>✦ Nhật ký minh bạch</span><span>✦ Hỗ trợ khi cần</span></div></div>{wallet}<div class="hero-orb"></div></section>
<section class="notice-strip"><span class="notice-icon">✧</span><div><b>Thông cáo tông môn</b><p>{esc(announcement or "Chào mừng đạo hữu đến với YS Shopping.")}</p></div><span class="strip-arrow">✦</span></section>
<section class="quick-grid"><a href="/wallet" class="quick-card"><span class="quick-icon">◈</span><span><b>Nạp số dư</b><small>Quét QR và gửi yêu cầu</small></span><i>↗</i></a><a href="#shop" class="quick-card"><span class="quick-icon">✧</span><span><b>Gian hàng số</b><small>Tài khoản · Mã code · Gói dịch vụ</small></span><i>↗</i></a><a href="/orders" class="quick-card"><span class="quick-icon">▤</span><span><b>Lịch sử giao dịch</b><small>Theo dõi đơn hàng của đạo hữu</small></span><i>↗</i></a></section>
<section class="section-head" id="shop"><div><span class="eyebrow">KHO BÁU BỒNG LAI</span><h2>Gian hàng <em>tiên phẩm</em></h2><p>Chọn danh mục, khám phá từng món hàng.</p></div><div class="catalog-controls"><input type="search" aria-label="Tìm sản phẩm" placeholder="Tìm sản phẩm..." data-product-search><select aria-label="Lọc danh mục" data-category-filter><option value="">Tất cả danh mục</option>{''.join('<option value="'+esc(cat)+'">'+esc(cat)+'</option>' for cat in sorted({p['category'] for p in products if p['category']}))}</select></div></section>
<div class="product-grid" data-product-grid>{catalog}</div>
<section class="bottom-cta"><div><span class="eyebrow">VẠN VẬT ĐỀU CÓ DUYÊN</span><h2>Giao dịch minh bạch,<br><em>an tâm hành tẩu.</em></h2><p>{esc(banner)}</p></div><a class="btn light" href="/wallet">Bắt đầu nạp tiền ↗</a></section>'''
        self.send_html(self.page("Trang chủ", body, self.session, wide=True))

    def login_get(self) -> None:
        body = f'''<section class="auth-layout"><div class="auth-art"><span class="eyebrow">KẾT DUYÊN TIÊN CẢNH</span><h1>Trở về<br><em>tông môn</em></h1><p>Đăng nhập để quản lý số dư, lưu lịch sử giao dịch và nhận bảo vật số.</p><div class="auth-ornament">✧　山海　✧</div></div><div class="panel form-panel"><span class="eyebrow">ĐĂNG NHẬP</span><h2>Chào mừng đạo hữu</h2><p class="muted">Nhập tài khoản đã đăng ký của ní.</p><form method="post" action="/login" class="stack">{self.hidden_csrf()}<label>Tên đăng nhập<input name="username" autocomplete="username" required maxlength="24"></label><label>Mật khẩu<input name="password" type="password" autocomplete="current-password" required></label><button class="btn primary full" type="submit">Đăng nhập ↗</button></form><p class="form-foot">Chưa có tài khoản? <a href="/register">Gia nhập tông môn</a></p></div></section>'''
        self.send_html(self.page("Đăng nhập", body, self.session, wide=True))

    def register_get(self) -> None:
        body = f'''<section class="auth-layout"><div class="auth-art"><span class="eyebrow">KHAI MỞ HỒ SƠ</span><h1>Gia nhập<br><em>tiên cảnh</em></h1><p>Tạo tài khoản để lưu các yêu cầu nạp tiền và đơn hàng của mình.</p><div class="auth-ornament">✧　蓬萊　✧</div></div><div class="panel form-panel"><span class="eyebrow">ĐĂNG KÝ</span><h2>Tạo tài khoản</h2><p class="muted">Tên đăng nhập 3–24 ký tự; mật khẩu ít nhất 10 ký tự.</p><form method="post" action="/register" class="stack">{self.hidden_csrf()}<label>Tên đăng nhập<input name="username" autocomplete="username" minlength="3" maxlength="24" pattern="[A-Za-z0-9_-]+" required></label><label>Email (không bắt buộc)<input name="email" type="email" autocomplete="email" maxlength="160"></label><label>Mật khẩu<input name="password" type="password" autocomplete="new-password" minlength="10" required></label><label>Nhập lại mật khẩu<input name="password2" type="password" autocomplete="new-password" minlength="10" required></label><button class="btn primary full" type="submit">Tạo tài khoản</button></form><p class="form-foot">Đã có tài khoản? <a href="/login">Đăng nhập</a></p></div></section>'''
        self.send_html(self.page("Đăng ký", body, self.session, wide=True))

    def login_post(self) -> None:
        username = clean_text(self.form.get("username"), 24)
        password = self.form.get("password", "")
        ip = self.client_address[0] if self.client_address else "unknown"
        now = int(time.time())
        with connect_db() as con:
            con.execute("DELETE FROM login_attempts WHERE created_at<?", (now - 900,))
            attempts = con.execute("SELECT COUNT(*) AS c FROM login_attempts WHERE ip=? AND username=? AND created_at>?", (ip, username.lower(), now - 900)).fetchone()["c"]
            if attempts >= 10:
                return self.redirect("/login?msg=Quá%20nhiều%20lần%20thử.%20Hãy%20đợi%2015%20phút&kind=error")
            user = con.execute("SELECT * FROM users WHERE username=? COLLATE NOCASE", (username,)).fetchone()
            if user:
                okay = verify_password(password, user["password_hash"])
            else:
                # Do a dummy KDF so nonexistent names do not return immediately.
                verify_password(password or "x", hash_password("dummy-password-only"))
                okay = False
            if not okay or not user or user["disabled"]:
                con.execute("INSERT INTO login_attempts(ip,username,created_at) VALUES(?,?,?)", (ip, username.lower(), now))
                return self.redirect("/login?msg=Thông%20tin%20đăng%20nhập%20không%20đúng%20hoặc%20tài%20khoản%20đang%20khóa&kind=error")
            con.execute("DELETE FROM login_attempts WHERE ip=? AND username=?", (ip, username.lower()))
        self._refresh_session(user["id"])
        return self.redirect("/?msg=Đăng%20nhập%20thành%20công&kind=ok")

    def register_post(self) -> None:
        username = clean_text(self.form.get("username"), 24)
        email = clean_text(self.form.get("email"), 160)
        password = self.form.get("password", "")
        password2 = self.form.get("password2", "")
        if not re.fullmatch(r"[A-Za-z0-9_-]{3,24}", username):
            return self.redirect("/register?msg=Tên%20đăng%20nhập%20chỉ%20dùng%20chữ,%20số,_%20và%20-&kind=error")
        if email and not re.fullmatch(r"[^\s@]+@[^\s@]+\.[^\s@]+", email):
            return self.redirect("/register?msg=Email%20không%20hợp%20lệ&kind=error")
        if len(password) < 10 or password != password2:
            return self.redirect("/register?msg=Mật%20khẩu%20cần%20từ%2010%20ký%20tự%20và%20hai%20ô%20phải%20trùng%20nhau&kind=error")
        try:
            with connect_db() as con:
                con.execute("BEGIN IMMEDIATE")
                cur = con.execute("INSERT INTO users(username,email,password_hash,role,created_at) VALUES(?,?,?,?,?)", (username, email, hash_password(password), "customer", utc_now()))
                audit(con, con.execute("SELECT * FROM users WHERE id=?", (cur.lastrowid,)).fetchone(), "register", "user", cur.lastrowid, "Tài khoản khách hàng được tạo")
                con.commit()
            self._refresh_session(cur.lastrowid)
            return self.redirect("/?msg=Đã%20tạo%20tài%20khoản%20thành%20công&kind=ok")
        except sqlite3.IntegrityError:
            return self.redirect("/register?msg=Tên%20đăng%20nhập%20đã%20tồn%20tại&kind=error")

