                rhtml.append(f'''<article class="order-admin-card"><div class="order-admin-top"><div><span class="eyebrow">ĐƠN #{r['id']}</span><h3>{esc(r['product_title'])}</h3><p>{esc(r['username'])} · {esc(r['created_at'][:16].replace('T',' '))}</p></div><div class="order-amount"><strong>{money(r['total'])}</strong><span class="status {esc(r['status'])}">{self.status_label(r['status'])}</span></div></div>{('<details class="delivery-details"><summary>Xem nội dung giao hàng</summary>'+self.delivery_html(r['delivery_text'])+'</details>') if r['delivery_text'] else ''}{controls}</article>''')
