            sale_html = ''.join(f'<li><b>{esc(p["title"])}</b> — {money(p["sale_price"])} đến {esc(p["sale_until"] or "chưa đặt hạn")}</li>' for p in sale_products) or '<li class="muted">Chưa có Flash Sale. Thiết lập trong biểu mẫu sửa sản phẩm.</li>'
            body = f'''<section class="panel form-panel admin-form"><span class="eyebrow">MÃ ƯU ĐÃI</span><h2>Tạo mã giảm giá</h2><form method="post" action="/admin/coupons/save" class="form-grid">{self.hidden_csrf()}<label>Mã (ví dụ TIENMON10)<input name="code" required pattern="[A-Za-z0-9_-]{{3,32}}" maxlength="32"></label><label>Kiểu giảm<select name="kind"><option value="percent">Phần trăm (%)</option><option value="fixed">Số tiền cố định (đ)</option></select></label><label>Giá trị<input name="value" type="number" min="1" max="100000000" required></label><label>Hạn dùng (để trống = không hạn)<input name="expires_at" type="datetime-local"></label><label>Số lượt dùng (0 = không giới hạn)<input name="uses_limit" type="number" min="0" value="0"></label><button class="btn primary" type="submit">Tạo mã giảm giá</button></form></section><section class="panel table-panel"><div class="section-head compact"><div><span class="eyebrow">MÃ ĐANG QUẢN LÝ</span><h2>Khuyến mãi</h2></div></div><div class="table-wrap"><table><thead><tr><th>Mã</th><th>Ưu đãi</th><th>Hạn dùng</th><th>Lượt dùng</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody>{crows}</tbody></table></div></section><section class="panel"><div class="section-head compact"><div><span class="eyebrow">FLASH SALE</span><h2>Giá ưu đãi sản phẩm</h2></div></div><p class="muted">Mở Sản phẩm & kho hàng, đặt giá khuyến mãi thấp hơn giá gốc và thời điểm kết thúc. Giá tự trở về giá gốc sau thời hạn.</p><ul class="flash-list">{sale_html}</ul><a href="/admin/products" class="btn ghost">Mở quản lý sản phẩm ↗</a></section>'''
